 for(let k=0;k<2;k++){const top=k*h/2+22,bottom=(k+1)*h/2-12,vals=frames.map(f=>channel.value(f,k)),lo=Math.min(0,...vals)<0?Math.min(-channel.minimum,...vals):0,hi=Math.max(channel.minimum,...vals),x=t=>42+(w-54)*t/xmax,z=v=>bottom-(bottom-top)*(v-lo)/(hi-lo);c.fillStyle='#9aabb7';c.fillText((channel.rider?(k?'Feet ':'Hands '):(k?'Rear ':'Front '))+channel.label,8,top-7);c.fillText(hi.toPrecision(3),4,top+8);if(lo<0)c.fillText(lo.toPrecision(3),4,bottom);c.strokeStyle='#344654';c.beginPath();c.moveTo(42,z(0));c.lineTo(w-12,z(0));c.stroke();c.strokeStyle=k?'#f2b373':'#84c8ff';c.beginPath();frames.forEach((f,i)=>i?c.lineTo(x(f.time),z(vals[i])):c.moveTo(x(f.time),z(vals[i])));c.stroke();c.strokeStyle='#c2a3ff';c.beginPath();c.moveTo(x(frames[index].time),top);c.lineTo(x(frames[index].time),bottom);c.stroke();}
