$('example').onchange=()=>{const a=normalized(experiment($('example').value,form.elements.bike.value));fill(a);if(['coast','sliding','drive','brake'].includes($('example').value)){$('forceAxis').value=['drive','brake'].includes($('example').value)?'spin':'slip';$('forceAxis').onchange();}calculate(a,$('example').value.startsWith('rider-')?'rider-z':undefined);};$('restore').onclick=()=>{if(!applied)return;stop();input=inputs(applied);dirty=false;fill(input);$('error').textContent='';controls();render();};$('cancel').onclick=()=>{edits();$('status').textContent='CANCELLED';};$('scrub').oninput=()=>{pause();index=Number($('scrub').value);elapsed=applied.frames[index].time;render();};$('reset').onclick=()=>{pause();index=0;elapsed=0;render();};$('step').onclick=()=>{pause();index=Math.min(index+1,applied.frames.length-1);elapsed=applied.frames[index].time;render();};$('play').onclick=()=>{if(playing){pause();return;}if(index===applied.frames.length-1){index=0;elapsed=0;}playing=true;$('play').textContent='Pause';lastStamp=0;animation=requestAnimationFrame(tick);};
function tick(stamp){if(!playing||dirty)return;if(lastStamp)elapsed+=Math.min((stamp-lastStamp)/1000,.05);lastStamp=stamp;while(index<applied.frames.length-1&&applied.frames[index+1].time<=elapsed)index++;render();if(index===applied.frames.length-1)pause();else animation=requestAnimationFrame(tick);}
$('load').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;edits();const ticket=revision;try{if(file.size>8*1024*1024)throw Error('Record exceeds 8 MiB.');const text=await file.text();if(ticket!==revision)return;calculate(inputFromRecord(JSON.parse(text.replace(/^\uFEFF/,''))));}catch(error){if(ticket===revision)reject(error);}};$('save').onclick=()=>{if(dirty||!applied)return;const url=URL.createObjectURL(new Blob([JSON.stringify(applied)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='bikelab-trail-bike.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
new ResizeObserver(()=>{draw();history();}).observe($('rig'));window.addEventListener('resize',()=>{draw();history();});window.addEventListener('pagehide',()=>{if(worker)edits();pause();});fill(input);calculate(input);
